add_action( 'wp_footer', 'perfectpixel_quantity_dropdown_script' );

function perfectpixel_quantity_dropdown_script() {
	if ( ! function_exists( 'is_product' ) || ! is_product() ) {
		return;
	}
	?>
	<script>
	document.querySelectorAll( 'form.cart input.qty' ).forEach( function ( input ) {
		if ( input.type === 'hidden' ) {
			return;
		}
		var limit = parseInt( <?php echo wp_json_encode( '{{qty_dropdown_max}}' ); ?>, 10 ) || 20;
		var min = parseFloat( input.min ) || 1;
		var step = parseFloat( input.step ) || 1;
		var max = input.max !== '' ? Math.min( parseFloat( input.max ), min + step * ( limit - 1 ) ) : min + step * ( limit - 1 );
		var select = document.createElement( 'select' );
		select.name = input.name;
		select.className = input.className;
		select.id = input.id;
		for ( var v = min; v <= max; v += step ) {
			var option = document.createElement( 'option' );
			option.value = option.textContent = v;
			if ( v === parseFloat( input.value ) ) {
				option.selected = true;
			}
			select.appendChild( option );
		}
		input.parentNode.replaceChild( select, input );
	} );
	</script>
	<?php
}
